--[[
    Perishable Foods - hooks that handle food and drinks as the player meets them.

    * loot filled into a container: generated by the world, already aged;
    * the player's inventory and nearby floor items, every 10 game minutes;
    * (the loot window is handled on the client, see PF_Client.lua).
]]

require "PerishableFoods/PF_Drinks"

if isClient() then return end -- multiplayer clients: the server does the work

local PF = PerishableFoods
local SCAN_RADIUS = 12

local function onFillContainer(roomName, containerType, container)
    if container and instanceof(container, "ItemContainer") then
        PF.processContainer(container, true)
    end
end

local function scanFloor(player)
    local cell = getCell()
    local px, py, pz = math.floor(player:getX()), math.floor(player:getY()), math.floor(player:getZ())
    for x = px - SCAN_RADIUS, px + SCAN_RADIUS do
        for y = py - SCAN_RADIUS, py + SCAN_RADIUS do
            local square = cell:getGridSquare(x, y, pz)
            if square then
                local objects = square:getWorldObjects()
                for i = 0, objects:size() - 1 do
                    local item = objects:get(i):getItem()
                    if item then PF.processItem(item, false) end
                end
            end
        end
    end
end

local function everyTenMinutes()
    if not PF.enabled() then return end
    local function handle(player)
        if player and not player:isDead() then
            PF.processContainer(player:getInventory(), false)
            scanFloor(player)
        end
    end
    if isServer() then
        local players = getOnlinePlayers()
        for i = 0, players:size() - 1 do handle(players:get(i)) end
    else
        for i = 0, getNumActivePlayers() - 1 do handle(getSpecificPlayer(i)) end
    end
end

Events.OnFillContainer.Add(onFillContainer)
Events.EveryTenMinutes.Add(everyTenMinutes)
